<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>İlan rezervasyonları</title><style>
*{box-sizing:border-box}body{font-family:system-ui;background:#f4f7f4;color:#26332b;margin:0}.wrap{max-width:1120px;margin:28px auto;padding:0 16px}.head{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}.muted{color:#718077;font-size:13px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters a{padding:8px 12px;border-radius:20px;background:#fff;border:1px solid #dfe8e1;color:#365746;text-decoration:none;font-size:13px}.filters a.active{background:#176b50;color:white}.item{background:white;border:1px solid #e4ebe5;border-radius:14px;padding:17px;margin:11px 0;display:grid;grid-template-columns:2fr 1.2fr 1fr 1.2fr;gap:14px;align-items:center}.tag{display:inline-block;padding:5px 9px;border-radius:20px;background:#edf5ef;font-size:12px}.actions form{display:flex;gap:7px;flex-wrap:wrap}.actions select,.actions button{padding:9px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}.actions button{background:#176b50;color:white;border:0;font-weight:750}.actions a{display:inline-block;margin-top:8px;color:#176b50;font-size:13px}.empty{background:white;padding:26px;text-align:center;border-radius:13px}@media(max-width:760px){.item{grid-template-columns:1fr;gap:10px;padding:15px}.actions form{display:grid;grid-template-columns:1fr;gap:9px}.actions select,.actions button{width:100%;min-height:44px}.wrap{margin:20px auto}}
</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><div class="head"><div><h1>İlan rezervasyonları</h1><p class="muted">Yalnızca size ait ilanların talepleri görüntülenir.</p></div><a href="<?= e(app_url('/vendor')) ?>">← Ev sahibi paneli</a></div><nav class="filters"><?php foreach([''=>'Tümü','pending'=>'Bekleyen','confirmed'=>'Onaylanan','cancelled'=>'İptal edilen','completed'=>'Tamamlanan'] as $key=>$label): ?><a class="<?= ($bookingFilter??'')===$key?'active':'' ?>" href="<?= e(app_url('/vendor/bookings'.($key!==''?'?status='.rawurlencode($key):''))) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
<?php foreach($bookings as $b): ?><article class="item"><div><strong><?= e($b['title']) ?></strong><p class="muted"><?= e($b['guest_name']) ?> · <?= e($b['guest_email']) ?><?= !empty($b['guest_phone'])?' · '.e($b['guest_phone']):'' ?></p><small><?= e($b['booking_code']) ?></small><?php if(!empty($b['early_checkin_requested'])||!empty($b['late_checkout_requested'])): ?><p class="muted">Ek talepler: <?= !empty($b['early_checkin_requested'])?'Erken giriş ('.number_format((float)$b['early_checkin_fee'],2,',','.').' '.e($b['currency']).')':'' ?> <?= !empty($b['late_checkout_requested'])?'Geç çıkış ('.number_format((float)$b['late_checkout_fee'],2,',','.').' '.e($b['currency']).')':'' ?></p><?php endif; ?></div><div><?= e(date('d.m.Y',strtotime($b['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($b['check_out']))) ?><p class="muted"><?= (int)$b['guests'] ?> misafir</p></div><div><strong><?= e(number_format((float)$b['total'],2,',','.')) ?> <?= e($b['currency']) ?></strong><p><span class="tag"><?= e(['pending'=>'Bekliyor','confirmed'=>'Onaylandı','cancelled'=>'İptal','completed'=>'Tamamlandı'][$b['status']]??$b['status']) ?></span></p></div><div class="actions"><?php if(in_array($b['status'],['pending','confirmed'],true)): ?><form method="post" action="<?= e(app_url('/vendor/bookings/status')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select name="status"><?php if($b['status']==='pending'): ?><option value="confirmed">Onayla</option><?php endif; ?><option value="cancelled">İptal et</option><?php if($b['status']==='confirmed'): ?><option value="completed">Tamamlandı</option><?php endif; ?></select><button type="submit">Uygula</button></form><?php endif; ?><?php if(!empty($b['guest_user_id'])): ?><a href="<?= e(app_url('/account/messages/'.(int)$b['id'])) ?>">Misafirle mesajlaş</a><?php endif; ?></div></article><?php endforeach; ?><?php if(!$bookings): ?><div class="empty">Bu filtrede rezervasyon bulunmuyor.</div><?php endif; ?><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>